  const two = parseAnswer(answer("twoFiles"), AT);
  expect(line(two).startsWith('files src/a.ts="export const a = 1;\\n" tests/a.test.ts="import { test, expect } from \\"vitest\\";'), "two files in targets order").toBe(true);
